    }

    #[test]
    fn len_chars_counts_unicode_scalars() {
        let doc = Document::from("aβ😀");
        assert_eq!(doc.len_chars(), 3);
    }

    #[test]
    fn from_str_keeps_text() {
        let doc = Document::from("hello");
        assert_eq!(doc.text().to_string(), "hello");
    }
}

